import { assetUrl } from '../assets/manifest';

/**
 * A short illustrated cinematic: panels (pixel-art vignettes) with typewriter text, an
 * optional effect each, tap to advance and «Saltar» (skip) from the first second.
 * Generic: the data is `content/<game>/cinematics/<id>.json`, generated by
 * `scripts/art/build-cinematics.ts` (format in docs/ART_CATALOG.md → «Reproductor de
 * cinemáticas»); the player knows nothing about any game.
 *
 * Panel images live under the game's `public/assets/cinematics/`, are drawn at an integer
 * scale with nearest-neighbour (black bands when it doesn't fit) and animated with the Web
 * Animations API — no per-frame JS. Unknown effects are ignored, as the format promises.
 * With `prefers-reduced-motion` only the short fade-in between panels stays.
 */

export interface CinematicPanel {
  id: string;
  /** File name under `assets/cinematics/`. */
  image: string;
  /** Shown one after another, sharing `durationMs` equally. */
  lines: string[];
  durationMs: number;
  effect?: string;
  effectParams?: Record<string, unknown>;
  /** Narration style hint (`comunicado` = a public announcement); only changes the look of the text. */
  voice?: string;
}

export interface Cinematic {
  /** Logical size of a panel, e.g. [320, 180]. */
  size: [number, number];
  panels: CinematicPanel[];
}

export interface CinematicOptions {
  /** Button label (Spanish, from the game's texts); defaults to «Saltar». */
  skipLabel?: string;
  /** Hint under the text. */
  nextHint?: string;
  /** Asked to play a named cue (`beep`, `jingle`) — the client maps it to its own sfx. */
  sound?: (cue: string) => void;
}

const TYPE_MS_PER_CHAR = 28;

const num = (v: unknown, fallback: number): number => (typeof v === 'number' ? v : fallback);
const pair = (v: unknown, fallback: [number, number]): [number, number] =>
  Array.isArray(v) && typeof v[0] === 'number' && typeof v[1] === 'number' ? [v[0], v[1]] : fallback;

/** Small deterministic generator, so particles don't change between two plays of a panel. */
function rng(seed: number): () => number {
  let s = seed >>> 0 || 1;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class CinematicPlayer {
  private root = document.querySelector<HTMLElement>('#cinematic')!;
  private anims: Animation[] = [];
  private timers: number[] = [];
  private onKey: ((ev: KeyboardEvent) => void) | null = null;
  private onResize: (() => void) | null = null;
  private finish: (() => void) | null = null;

  constructor(private options: CinematicOptions = {}) {}

  get isPlaying(): boolean {
    return this.finish !== null;
  }

  /** Plays `cinematic`, then `done` (also when skipped). With nothing to play, goes straight on. */
  play(cinematic: Cinematic | undefined, done: () => void): void {
    if (!cinematic || cinematic.panels.length === 0 || this.finish) return done();
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const [W, H] = cinematic.size;

    const skip = document.createElement('button');
    skip.className = 'skip';
    skip.textContent = this.options.skipLabel ?? 'Saltar';
    const count = document.createElement('span');
    count.className = 'count';
    const stage = document.createElement('div');
    stage.className = 'stage';
    const shaker = document.createElement('div');
    shaker.className = 'shaker';
    const layer = document.createElement('div');
    layer.className = 'layer';
    const img = document.createElement('img');
    img.alt = '';
    img.draggable = false;
    layer.append(img);
    shaker.append(layer);
    const fx = document.createElement('div');
    fx.className = 'fx';
    stage.append(shaker, fx);
    const caption = document.createElement('div');
    caption.className = 'caption';
    caption.setAttribute('aria-live', 'polite');
    const text = document.createElement('p');
    const hint = document.createElement('small');
    hint.textContent = this.options.nextHint ?? 'Toca para seguir ▸';
    caption.append(text, hint);
    const group = document.createElement('div');
    group.className = 'group';
    group.append(stage, caption);
    this.root.replaceChildren(skip, count, group);
    this.root.setAttribute('role', 'dialog');
    this.root.setAttribute('aria-label', 'Cinemática');
    this.root.hidden = false;

    // Integer scale with black bands (docs/ART_CATALOG.md); at least 1.
    let scale = 1;
    const fit = (): void => {
      scale = Math.max(1, Math.floor(Math.min((window.innerWidth - 16) / W, (window.innerHeight * 0.55) / H)));
      stage.style.width = `${W * scale}px`;
      stage.style.height = `${H * scale}px`;
      this.root.style.setProperty('--stage-w', `${W * scale}px`);
      if (img.naturalWidth) {
        img.style.width = `${img.naturalWidth * scale}px`;
        img.style.height = `${img.naturalHeight * scale}px`;
      }
    };
    fit();
    this.onResize = fit;
    window.addEventListener('resize', fit);

    for (const p of cinematic.panels) new Image().src = assetUrl(`assets/cinematics/${p.image}`);

    let panelIndex = -1;
    let lineIndex = 0;
    let typing: { full: string; stop: () => void } | null = null;
    let panel: CinematicPanel | undefined;
    let lineTimer = 0;

    const clearTimers = (): void => {
      for (const t of this.timers) window.clearTimeout(t);
      this.timers = [];
    };
    const after = (ms: number, fn: () => void): void => {
      this.timers.push(window.setTimeout(fn, ms));
    };
    const clearEffects = (): void => {
      for (const a of this.anims) a.cancel();
      this.anims = [];
      fx.replaceChildren();
      clearTimers();
    };
    const animate = (el: HTMLElement, keyframes: Keyframe[], options: KeyframeAnimationOptions): void => {
      this.anims.push(el.animate(keyframes, options));
    };

    const end = (): void => {
      if (!this.finish) return;
      this.finish = null;
      window.clearTimeout(lineTimer);
      typing?.stop();
      clearEffects();
      window.removeEventListener('resize', fit);
      if (this.onKey) window.removeEventListener('keydown', this.onKey);
      this.onKey = null;
      this.onResize = null;
      this.root.hidden = true;
      this.root.replaceChildren();
      done();
    };
    this.finish = end;

    const startTyping = (full: string, lineMs: number): void => {
      typing?.stop();
      text.textContent = '';
      const perChar = Math.max(8, Math.min(TYPE_MS_PER_CHAR, (lineMs * 0.6) / Math.max(1, full.length)));
      const started = performance.now();
      const id = window.setInterval(() => {
        const n = Math.min(full.length, Math.floor((performance.now() - started) / perChar));
        text.textContent = full.slice(0, n);
        if (n >= full.length) stop();
      }, 30);
      const stop = (): void => {
        window.clearInterval(id);
        text.textContent = full;
        if (typing && typing.full === full) typing = null;
      };
      typing = { full, stop };
    };

    const showLine = (i: number): void => {
      if (!panel) return;
      lineIndex = i;
      const lineMs = panel.durationMs / Math.max(1, panel.lines.length);
      startTyping(panel.lines[i] ?? '', lineMs);
      window.clearTimeout(lineTimer);
      lineTimer = window.setTimeout(next, lineMs);
    };

    const next = (): void => {
      if (!panel) return;
      window.clearTimeout(lineTimer);
      if (lineIndex + 1 < panel.lines.length) showLine(lineIndex + 1);
      else showPanel(panelIndex + 1);
    };

    const showPanel = (i: number): void => {
      clearEffects();
      typing?.stop();
      if (i >= cinematic.panels.length) return end();
      panelIndex = i;
      panel = cinematic.panels[i]!;
      count.textContent = `${i + 1}/${cinematic.panels.length}`;
      caption.className = `caption${panel.voice ? ` voice-${panel.voice}` : ''}`;
      img.onload = () => {
        fit();
        runEffect(panel!);
      };
      img.src = assetUrl(`assets/cinematics/${panel.image}`);
      if (img.complete && img.naturalWidth) {
        img.onload = null;
        fit();
        runEffect(panel);
      }
      // A short fade-in between panels, kept even with reduced motion.
      animate(stage, [{ opacity: 0 }, { opacity: 1 }], { duration: 220, fill: 'both' });
      showLine(0);
    };

    // --- Effects -------------------------------------------------------------------

    const particles = (n: number, make: (el: HTMLElement, r: () => number) => Keyframe[], opts: (r: () => number) => KeyframeAnimationOptions, seed: number): void => {
      const r = rng(seed);
      for (let k = 0; k < n; k++) {
        const el = document.createElement('i');
        const keyframes = make(el, r);
        fx.append(el);
        animate(el, keyframes, opts(r));
      }
    };
    const px = (v: number): string => `${Math.round(v * scale)}px`;

    const runEffect = (p: CinematicPanel): void => {
      if (reduced) return;
      const params = p.effectParams ?? {};
      const D = p.durationMs;
      const jitter = (amp: number, steps = 8): Keyframe[] => {
        const r = rng(7);
        return Array.from({ length: steps + 1 }, (_, k) => (k === steps ? { transform: 'translate(0,0)' } : { transform: `translate(${px((r() - 0.5) * 2 * amp)}, ${px((r() - 0.5) * 2 * amp)})` }));
      };
      switch (p.effect) {
        case 'fade':
          animate(layer, [{ opacity: 0 }, { opacity: 1 }], { duration: Math.min(1600, D * 0.3), fill: 'both' });
          if (Array.isArray(params.pulse)) {
            const [gx, gy] = pair(params.pulse, [W / 2, H / 2]);
            const glow = document.createElement('i');
            glow.className = 'glow';
            glow.style.left = px(gx - 40);
            glow.style.top = px(gy - 40);
            glow.style.width = glow.style.height = px(80);
            fx.append(glow);
            animate(glow, [{ opacity: 0.1 }, { opacity: 0.75 }], { duration: 1300, direction: 'alternate', iterations: Infinity, easing: 'ease-in-out' });
          }
          break;
        case 'pan': {
          const [fx0, fy0] = pair(params.from, [0, 0]);
          const [tx, ty] = pair(params.to, [0, 0]);
          animate(layer, [{ transform: `translate(${px(-fx0)}, ${px(-fy0)})` }, { transform: `translate(${px(-tx)}, ${px(-ty)})` }], { duration: D, easing: 'ease-in-out', fill: 'forwards' });
          if (params.flashes) {
            const flash = document.createElement('i');
            flash.className = 'flash';
            fx.append(flash);
            animate(flash, [{ opacity: 0 }, { opacity: 0.85, offset: 0.04 }, { opacity: 0, offset: 0.1 }, { opacity: 0, offset: 0.38 }, { opacity: 0.7, offset: 0.4 }, { opacity: 0, offset: 0.47 }, { opacity: 0, offset: 0.7 }, { opacity: 0.9, offset: 0.72 }, { opacity: 0 }], { duration: 3500, iterations: Infinity });
          }
          break;
        }
        case 'zoom': {
          const [cx, cy] = pair(params.centre, [W / 2, H / 2]);
          layer.style.transformOrigin = `${px(cx)} ${px(cy)}`;
          animate(layer, [{ transform: `scale(${num(params.from, 1)})` }, { transform: `scale(${num(params.to, 1.2)})` }], { duration: D, easing: 'ease-in-out', fill: 'forwards' });
          break;
        }
        case 'shake': {
          const amp = num(params.intensity, 1) * 1.5;
          animate(shaker, jitter(amp, 12), { delay: num(params.atMs, 0), duration: 700, fill: 'none' });
          break;
        }
        case 'flicker':
          animate(layer, [{ opacity: 1 }, { opacity: 0.55, offset: 0.12 }, { opacity: 1, offset: 0.22 }, { opacity: 0.8, offset: 0.4 }, { opacity: 0.3, offset: 0.5 }, { opacity: 1, offset: 0.6 }, { opacity: 0.9, offset: 0.8 }, { opacity: 1 }], { duration: 1100, iterations: Infinity, easing: 'steps(1, end)' });
          break;
        case 'pulse': {
          const veil = document.createElement('i');
          veil.className = 'veil';
          veil.style.background = typeof params.color === 'string' ? params.color : '#e0302a';
          fx.append(veil);
          animate(veil, [{ opacity: 0 }, { opacity: 0.38 }], { duration: 1200, direction: 'alternate', iterations: Infinity, easing: 'ease-in-out' });
          break;
        }
        case 'sink':
          layer.style.transformOrigin = '50% 0';
          animate(layer, [{ transform: 'translateY(0) scale(1)', filter: 'brightness(1)' }, { transform: `translateY(${px(6)}) scale(1.05)`, filter: 'brightness(0.65)' }], { duration: D, fill: 'forwards', easing: 'ease-in' });
          break;
        case 'fall': {
          const [sx, sy] = pair(params.scroll, [0, 0]);
          animate(layer, [{ transform: 'translate(0,0)' }, { transform: `translate(${px(sx)}, ${px(sy)})` }], { duration: D, easing: 'ease-in', fill: 'forwards' });
          animate(shaker, jitter(num(params.shake, 1), 10), { duration: 260, iterations: Infinity });
          break;
        }
        case 'spotlight': {
          const dark = document.createElement('i');
          dark.className = 'veil spot';
          fx.append(dark);
          animate(dark, [{ opacity: 1 }, { opacity: 0.5 }], { duration: Math.min(2500, D * 0.5), fill: 'forwards', easing: 'ease-out' });
          animate(layer, [{ opacity: 0 }, { opacity: 1 }], { duration: 900, fill: 'both' });
          break;
        }
        case 'crumble':
          animate(shaker, jitter(1, 10), { duration: 340, iterations: Infinity });
          particles(
            22,
            (el, r) => {
              const s = 2 + Math.floor(r() * 3);
              el.style.cssText = `left:${px(r() * W)};top:0;width:${px(s)};height:${px(s)};background:#3a3038;`;
              return [{ transform: `translateY(${px(-8)})` }, { transform: `translateY(${px(H + 8)})` }];
            },
            (r) => ({ duration: 700 + r() * 900, delay: -r() * 1500, iterations: Infinity, easing: 'ease-in' }),
            11,
          );
          break;
        case 'confetti': {
          const colours = ['#ffd24a', '#ff4f8b', '#45d4ff', '#7dff7a', '#ffffff'];
          particles(
            44,
            (el, r) => {
              const s = 2 + Math.floor(r() * 2);
              el.style.cssText = `left:${px(r() * W)};top:0;width:${px(s)};height:${px(s * 1.6)};background:${colours[Math.floor(r() * colours.length)]};`;
              const sway = (r() - 0.5) * 30;
              return [{ transform: `translate(0, ${px(-10)}) rotate(0deg)` }, { transform: `translate(${px(sway)}, ${px(H + 10)}) rotate(${Math.round(r() * 720)}deg)` }];
            },
            (r) => ({ duration: 2200 + r() * 2200, delay: -r() * 3000, iterations: Infinity }),
            23,
          );
          break;
        }
        case 'blink':
          animate(layer, [{ opacity: 0 }, { opacity: 1, offset: 0.1 }, { opacity: 0, offset: 0.16 }, { opacity: 1, offset: 0.26 }, { opacity: 1 }], { duration: 1500, fill: 'both', easing: 'steps(1, end)' });
          break;
        case 'drop':
          animate(layer, [{ transform: `translateY(${px(-36)})`, opacity: 0 }, { transform: 'translateY(0)', opacity: 1, offset: 0.5 }, { transform: `translateY(${px(-7)})`, offset: 0.68 }, { transform: 'translateY(0)', offset: 0.82 }, { transform: `translateY(${px(-2)})`, offset: 0.92 }, { transform: 'translateY(0)' }], { duration: 1000, fill: 'both' });
          break;
        default:
          break; // no effect, or one this player doesn't know: the still image is fine
      }
      if (params.particles === 'rain') {
        particles(
          36,
          (el, r) => {
            el.style.cssText = `left:${px(r() * (W + 20))};top:${px(-8)};width:${px(1)};height:${px(6)};background:rgba(190,210,255,0.55);`;
            return [{ transform: 'translate(0,0)' }, { transform: `translate(${px(-8)}, ${px(H + 10)})` }];
          },
          (r) => ({ duration: 450 + r() * 400, delay: -r() * 800, iterations: Infinity }),
          5,
        );
      } else if (params.particles === 'steam') {
        particles(
          9,
          (el, r) => {
            const s = 10 + Math.floor(r() * 10);
            el.style.cssText = `left:${px(W * (0.25 + r() * 0.5))};top:${px(H * 0.6)};width:${px(s)};height:${px(s)};border-radius:50%;background:rgba(255,255,255,0.14);`;
            return [{ transform: 'translateY(0) scale(1)', opacity: 0.6 }, { transform: `translateY(${px(-34)}) scale(2)`, opacity: 0 }];
          },
          (r) => ({ duration: 2500 + r() * 2000, delay: -r() * 3000, iterations: Infinity }),
          9,
        );
      }
      const cue = params.sound;
      if (typeof cue === 'string') after(cue === 'jingle' ? 500 : 0, () => this.options.sound?.(cue));
    };

    // --- Input ---------------------------------------------------------------------

    const tap = (): void => {
      if (typing) typing.stop();
      else next();
    };
    this.root.onclick = (ev) => {
      if ((ev.target as HTMLElement).closest('.skip')) return;
      tap();
    };
    skip.onclick = end;
    this.onKey = (ev) => {
      if (ev.key === 'Escape') end();
      else if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        tap();
      }
    };
    window.addEventListener('keydown', this.onKey);

    showPanel(0);
  }
}
